/**
 * ⚠️ GENERATED FILE — DO NOT EDIT BY HAND.
 *
 * Source of truth: games/beads/design/levels/{manifest.json,palette.json,singles/,plates/}
 * Regenerate:      node tools/scripts/sync-levels-data.mjs --game=beads
 * Drift guard:     pnpm run levels:check（pnpm run verify 内；覆盖面断言见 WXG-T-048）
 *
 * Why a generated module instead of importing the JSON directly: Cocos Creator
 * only loads assets under its own `assets/` tree, and browsers cannot import
 * JSON in an ES module without an import attribute. A plain TS module works
 * everywhere — Cocos, vitest, tsc and the browser harness alike (breakout 判例).
 */

export interface BeadsLevelRaw {
  /**
   * 本关的**稳定内容身份** token（ADR-0034 DEC-1/DEC-2 · §6 S-1；判据 = `gdd/save-progress.md` v1.3 §8-22）：
   * 生成期从 `manifest.entries[].uid` 纯函数派生并注入为记录**首键**（`single`/`boss` = uid 原样如 `L00001`；
   * `plate` 的第 c 格（c≥2）= `L000NN#c`，1-based 格序，首格不加后缀）。⇒ 它是**存档星账的记账轴**（「这一关
   * 几星」只取决于它是哪一关），与下面数值 `id`（= 装配下标 + 1，仅展示/几何轴）**解耦**；关表插删调序时
   * `id` 会变而本字段不动。⛔ 源关卡 JSON 不得手写（生成期拒收：第二真源），也由断言保证全表唯一且与装配
   * 槽序同命。运行时唯一消费点 = 存档读/写两个边界（`game/save-schema.ts` 归一化与 `BeadsGame` 镜像）。
   */
  readonly uid: string;
  readonly id: number;
  /** 内部名（studio 生成串，⛔ 不上屏）。 */
  readonly name: string;
  /**
   * 本关所属**大关名**（可选）：仅该章收尾关（boss）携带，由 `sync-levels-data.mjs` 生成期
   * 自章 `chapters/<id>.json` 的 `title` 注入（追加在对象末尾）。⛔ 源关卡 JSON 不得手写
   * （生成期断言拒收——展示名唯一真源 = 所属章，§11.7）。运行时 = 主菜单橱窗木牌关名
   * （`drawPlateTitle`）；缺省 ⇒ 木牌只显关序「第 N 关」。
   */
  readonly title?: string;
  readonly cols: number;
  readonly rows: number;
  readonly time: number;
  /**
   * 错位交换对 `[[r1,c1,r2,c2], ...]`（levels-spec v1.2 §2.1 / systems-index
   * v1.23 §3.13）：按数组序对「pattern 全满」的可填格珠两两交换 ⇒ 初始错位局面。
   * 对数 k ∈ [MISPLACED_PAIRS_MIN(1), MISPLACED_PAIRS_MAX(8)]。
   * ⛔ `spawnInterval` 已随供料关停在 version 2 清理删除（E5）。
   */
  readonly swaps: readonly (readonly [number, number, number, number])[];
  /**
   * 环长分布（v1.23 增补，**建议值、不冻结**）：`short` 全 2-环 / `mixed` 长短
   * 混合 / `long` 偏长环。8 关数据暂一律 `short`（恒等式 misplaced = 2k 优先，
   * 长环与 levels-spec §2.1 恒等式冲突，已回传）。
   */
  readonly cycleProfile: 'short' | 'mixed' | 'long';
  /** Decoy colour characters (pattern charset, never part of the pattern). */
  readonly decoys: readonly string[];
  /**
   * 全错位初盘（可选；v1.3）。rowstring，字符集同 `pattern`（`.x1-9A-Z`），逐格给出
   * **初始珠色**。存在则**替代 `swaps`** 作初盘真源（引擎直读装配、零 RNG ⇒ 输出确定），
   * 用于表达「成片错豆」（swaps 封顶 8 对 ≤16 颗不够）。BOOT 校验：形状一致 +
   * 可填轮廓逐格匹配 pattern + 每色珠数守恒 + 错位格数 ≥1（不强制 100% 全错）。
   * 缺省 ⇒ 走 `swaps` 路径（旧语义零扰动）。见 levels-spec §2.2 / systems-index §3.13。
   */
  readonly misplaced?: readonly string[];
  /**
   * Pattern rows, **top to bottom**. Charset `BEAD_CHARSET = ".x1-9A-Z"`
   * (`.` = empty slot, `x` = locked bead, `1-9`+`A-Z` = palette index 1–35).
   * ⚠️ §3.2 v1.55 raised the ceiling 10→35 (= the one-char-per-cell rowstring
   * encoding limit). **Uppercase only**: `x` = locked, `X` = index 33
   * (`Y` = 34, `Z` = 35) — the validator must stay case-sensitive.
   * Decode table: `config/bead-charset.ts`.
   */
  readonly pattern: readonly string[];
  /**
   * 本关品牌色板引用（v1.40）：slug ↔ `games/beads/art/<slug>.json`
   * （如 `'artkal-s'`）。与 {@link paletteCodes} 成对出现；缺省 ⇒ demo 默认色板。
   * ⚠️ **§3.2 v1.55 后条件必携**：`pattern` 最大色索引 > demo 色板长度时，成对字段
   * 不再可选（BOOT 硬校，否则越界索引静默兑炭黑）。hex 不随关卡携带 —— 只住品牌
   * 生成物（`palettes-data.ts`，art/ 编译期打包）。
   */
  readonly palette?: string;
  /**
   * 本关用到的品牌色号（v1.40）：紧凑序，`paletteCodes[colorIdx-1]` ↔ 索引
   * colorIdx，逐项存在于 `PALETTES[palette].codes`。上限随 `BEAD_COLOR_MAX`（§3.2
   * v1.55：**≤ 35**，旧值 10）。缺省 ⇒ demo 默认色板（仅当索引不超 demo 色板长度）。
   */
  readonly paletteCodes?: readonly string[];
  /**
   * **整套皮肤引用**（EP12-S9，可选；仅 beads-studio 在线导入通道携带）：值 = 游戏侧
   * 已注册皮肤 id（`config/skins/registry` 白名单）。**引用 id，不传数据本体**；
   * 关卡表真源（`design/levels/`）**不携带**此字段（皮肤是运行时设置，不入关表）。
   * 校验口径：类型错 ⇒ `validateBeadsLevel` 拒收；字符串未注册 ⇒ 校验放行，
   * 由 `importLevel` 回落默认肤 + 告警（K-064「谎报值不采信」——未注册不等于非法关卡）。
   */
  readonly skin?: string;
}

export interface LevelsData {
  readonly version: number;
  readonly gameId: string;
  /**
   * 默认珠色板（可选，v1.40）：demo 关卡（无逐关 `paletteHex`）的渲染色板，
   * 值 = 原 art-bible §3.2 十色（v1.40 起真源降级为关卡数据，`game-10.json` 已删除）。
   */
  readonly palette?: readonly string[];
  readonly description?: string;
  readonly levels: readonly BeadsLevelRaw[];
}

